svg.script:
(function(){
  var svg=document.getElementById('gla-svg');
  if(!svg||svg.getAttribute('data-gla'))return;
  svg.setAttribute('data-gla','1');
  var get=function(id){return document.getElementById(id)};
  var V=140, G=[380,650,920], P=[530,800,1070], X0=40, SP=270, SD=0.3;
  var DT=150/V, TPU=0.8*DT, CHV=120, CHL=64, C45=0.7071;
  var S=[],TG=[],TD=[],TC=[];
  for(var i=0;3>i;i++){
    S.push(SD+i*SP/V);
    TG.push(S[i]+(G[i]-9-X0)/V);        // 物品前沿 (中心-9px) 到达光束 = 落沿
    TD.push(TG[i]+DT);                   // 物品中心到达推料点 (D=150px)
    TC.push(S[i]+(150-X0)/V);            // 物品中心过相机
  }
  var TEND=TD[2]+0.9+1.8;
  function ease(p){if(0>=p)return 0;if(p>=1)return 1;return p*p*(3-2*p)}
  function rodY(t,i){
    var e=ease((t-TG[i])/TPU)-ease((t-(TD[i]+0.35))/0.7); // 推出 - 收回(物品已越过)
    if(0>e)e=0;if(e>1)e=1;
    return 438-36*e;
  }
  var DEF='▶ 循环演示 · 带速 1.0 m/s（1px≈3.3mm · 时间 2:1 放慢 · 件距 ≥ 0.9m）';
  function render(t){
    var tx=(t*V)%80;
    get('gla-treads').setAttribute('transform','translate('+tx.toFixed(2)+',0)');
    var ang=((t*V)/16*57.2958)%360;
    get('gla-spoke-1').setAttribute('transform','rotate('+ang.toFixed(1)+' 70 400)');
    get('gla-spoke-2').setAttribute('transform','rotate('+ang.toFixed(1)+' 1110 400)');
    var best=-1,bmsg=DEF;
    var camOn=false;
    for(var j=0;3>j;j++){if(t>=TC[j]){if(TC[j]+0.5>t)camOn=true;}}
    for(var i=0;3>i;i++){
      var s=S[i],tg=TG[i],td=TD[i],tc=TC[i];
      var op=0,x=X0,y=400;
      if(t>=s){
        if(td>t){x=X0+(t-s)*V;op=1;}
        else{
          var cs=(t-td)*CHV;
          if(cs>CHL){op=0;}
          else{
            var cc=Math.min(cs,CHL);
            x=P[i]+C45*cc; y=400+C45*cc; // 从推料点起沿 45° 滑入料道
            op=cs>CHL-14?(CHL-cs)/14:1;
          }
        }
      }
      get('gla-obj-'+(i+1)).setAttribute('opacity',op.toFixed(2));
      get('gla-obj-'+(i+1)).setAttribute('transform','translate('+x.toFixed(1)+','+y.toFixed(1)+')');
      // 光门挡光: 物品整体在光束内 (前沿 380 → 后沿 380+18px)
      var go=0;
      if(t>=tg){
        if(tg+18/V>=t)go=1;
        else if(tg+18/V+0.25>=t)go=1-(t-tg-18/V)/0.25;
      }
      get('gla-gate-'+(i+1)).setAttribute('opacity',go.toFixed(2));
      // 推杆
      var ry=rodY(t,i),rod=get('gla-rod-'+(i+1));
      rod.setAttribute('y2',ry.toFixed(1));
      rod.setAttribute('stroke',430>ry?'var(--gate-acc,#fb923c)':'var(--gate-fg,#e6e6e6)');
      // 料道高亮 (物品在道内)
      var ca=0;
      if(t>=td){if(td+0.9>=t)ca=0.45;}
      get('gla-chute-'+(i+1)).setAttribute('stroke-opacity',(0.30+ca).toFixed(2));
      // 状态行: 取 已发生的最近事件
      function ev(tt,msg){if(t>=tt){if(tt>best){best=tt;bmsg=msg;}}}
      ev(tc,'t0 识别 · 物品 '+(i+1)+'（HuskyLens 2 → 分拣器 '+(i+1)+' · 像素 x/y/w/h 透传）');
      ev(tg,'光门 '+(i+1)+' 落沿 → 推杆 '+(i+1)+' 推出开始（行程 400ms · 时间 2:1 放慢）');
      ev(td,'物品 '+(i+1)+' 到达推料点 · 拨入 '+(i+1)+' 号料道 ✓');
    }
    // 相机识别闪烁 (任一物品过相机 0.5s 内)
    get('gla-fan').setAttribute('opacity',camOn?'0.35':'0.10');
    get('gla-cam').setAttribute('stroke',camOn?'var(--gate-acc,#fb923c)':'var(--gate-bd,#262b36)');
    get('gla-status').textContent=bmsg;
  }
  // ---- 数字孪生同步模式: 页面轮询网关(health/motion)注入真实状态; 离线回落循环演示 ----
  var twinMode=false, twinData=null;
  var PXM=303.0; // 1px≈3.3mm → 1m≈303px
  var jobMats=[null,null,null]; // 每分拣器任务物料 {m:变体键, label:'香蕉 ×2', color:'#fbbf24'} (页面 setJob 注入)
  var VARKEYS=['block','banana','pear','red_apple','green_apple'];
  function setVariant(i,key){
    for(var k=0;5>k;k++){
      get('gla-obj-'+(i+1)+'-'+VARKEYS[k]).setAttribute('display',(VARKEYS[k]===key)?'inline':'none');
    }
    var jm=jmat(i);
    if(jm){
      if(jm.color)get('gla-obj-'+(i+1)+'-block').setAttribute('fill',jm.color);
    }
  }
  function showLabel(i){
    var jm=jmat(i);
    if(!jm)return;
    var lb=get('gla-jlabel-'+(i+1));
    lb.setAttribute('opacity','1');
    lb.setAttribute('fill',jm.color);
    if(lb.textContent!==jm.label)lb.textContent=jm.label;
  }
  function hideLabel(i){get('gla-jlabel-'+(i+1)).setAttribute('opacity','0');}
  // ---- 全旅程回放 (孪生模式): 推料期间停带, 推完恢复 (与固件 BeltHold 同口径) ----
  // 带面时间轴 beltT: 只累计带子实际在转的时间 → 停带时带纹/物品/轮辐同步冻结,
  // 恢复不跳帧. 物品位置由 beltT 导出 → 物品永远贴带面走 (无相对滑动/加速).
  // 模拟源: 全旅程 (带首装料 → 过相机识别 → 光门 → 推杆拨入) + 环境供血
  // (间距不均匀, 无指令直通不截留). 真实源: 事件驱动 — 物品按实际状态出现在
  // 光门处 (armed 事件), 无事件 = 只有皮带按实际运行, 不虚构任何物品.
  var journey=[null,null,null];   // 每分拣器 {phase:'travel'|'armed'|'busy'|'wait', x0, b0, tArmed, tBusy, tWait, qty, left, task, pass}
  var lastArmedMs=[0,0,0], lastBusyMs=[0,0,0], booted=false;
  var srcMode='sim';             // setSrc 注入: sim=本地孪生 / device=物理设备
  var beltT=0, lastFrameMs=0;    // 带面时间轴 (ms)
  var VJ=140;                    // 带面/物品行走速度 px/s (2:1 放慢口径; 带纹与物品同速)
  var BEND=1140;                 // 带面右端 (下游出口): 无指令物品直通从此处离场
  var CAMX=150;                  // HuskyLens 2 相机 x (识别内容显示位置)
  var visLabel='', visUntil=0;   // 相机识别显示: 内容 + 墙钟截止
  var gateLit=[false,false,false]; // 本帧: 各门是否有物品在过门时间窗 (多物品 OR, 循环后统一点亮)
  function gateOr(j){ // 物品过门时间窗 (带面时间: 门前 200ms → 门后 900ms, 掉帧不丢)
    for(var gk=0;3>gk;gk++){
      if(G[gk]>=j.x0){
        var tc=j.b0+(G[gk]-j.x0)/VJ*1000; // 过门时刻 (带面时间)
        if(beltT>=tc-200){if(tc+900>=beltT)gateLit[gk]=true;}
      }
    }
  }
  function startJourney(i,xFrom,now,kind){
    var jm=jobMats[i];
    var qty=jm?jm.qty:1;
    journey[i]={phase:'travel',x0:xFrom,b0:beltT,left:Math.max(0,qty-1),
                qty:qty,task:!!jm,pass:(kind==='pass'),tArmed:0,tBusy:0,tWait:0};
    if(kind==='gate'||kind==='push')setVision(i,now); // 相机已识别过 (任务物料): 视场处显示识别内容
  }
  function setVision(i,now){ // 相机处显示识别内容 (物料名 + 去向)
    var jm=jmat(i);
    var nm=jm?String(jm.label).split(' × ')[0]:'物品';
    var j=journey[i], tag='';
    if(j){
      if(j.pass)tag=' · 无指令直通';
      else if(j.task)tag=' → '+(i+1)+'号仓';
    }
    visLabel=nm+tag;
    visUntil=now+2600;
  }
  var DEMOS=[{m:'banana',label:'香蕉',color:'#fbbf24'},
             {m:'pear',label:'梨',color:'#a3d977'},
             {m:'red_apple',label:'红苹果',color:'#ef4444'},
             {m:'green_apple',label:'绿苹果',color:'#4ade80'},
             {m:'block',label:'蓝方块',color:'#60a5fa'}];
  function demoPick(){ // 循环演示每轮随机取 3 种物料 (模拟混合带)
    var pool=DEMOS.slice();
    for(var r=2;r>=0;r--){
      var idx=Math.floor(Math.random()*(r+1));
      var tmp=pool[0];pool[0]=pool[idx];pool[idx]=tmp;
      jobMats[r]=pool[0];pool.splice(0,1);
    }
    for(var di=0;3>di;di++){
      setVariant(di,jobMats[di].m);
      showLabel(di);
    }
  }
  // ---- 环境供血 (孪生 + 模拟数据源): 无指令时随机物料在带面持续行走 —
  //      带首出现, 缓行过 HuskyLens 2 (识别中), 依次经过三路光门 (光门亮灯,
  //      推杆不动作), 直通到带尾离场. 不截留任何物品: 收到指令后, 对应物料
  //      才按视觉识别结果在指定仓库拨入 (见下方任务旅程). 纯客户端时间线
  //      (不 /dispatch, 不记台账), 物料池为全量 8 种 (block 变体随颜色区分)
  var POOL8=[
    {m:'banana',label:'香蕉',color:'#fbbf24'},{m:'pear',label:'梨',color:'#a3d977'},
    {m:'red_apple',label:'红苹果',color:'#ef4444'},{m:'green_apple',label:'绿苹果',color:'#4ade80'},
    {m:'block',label:'红色方块',color:'#ef4444'},{m:'block',label:'绿色方块',color:'#4ade80'},
    {m:'block',label:'黄色方块',color:'#facc15'},{m:'block',label:'蓝色方块',color:'#60a5fa'}];
  var nextAmb=0;
  function jmat(i){var jj=journey[i];return jj?(jj.mat?jj.mat:jobMats[i]):jobMats[i];} // 旅程物料: 供血项自带, 任务项取注入
  function twinFrame(now){
    var td=twinData||{};
    gateLit[0]=false;gateLit[1]=false;gateLit[2]=false; // 多物品 OR 聚合: 每帧从头累加
    // 推料窗口: 任一旅程处于 armed/busy (推杆推入中) → 全带停止, 推完才恢复
    var pushing=false;
    for(var pi=0;3>pi;pi++){
      var pj=journey[pi];
      if(pj){
        if('armed'===pj.phase||'busy'===pj.phase){pushing=true;break;}
      }
    }
    var beltOn=true;
    if(pushing)beltOn=false;
    else{
      if('device'===srcMode){if(!td.belt_on)beltOn=false;} // 真实源: 跟实际带态; 模拟源: 常开 (环境供血)
    }
    // 带面时间轴: 只在带子转时累加 (停带冻结, 恢复不跳帧; 物品由 beltT 导出, 贴带面走)
    if(lastFrameMs){
      var dtnow=now-lastFrameMs;
      if(dtnow>100)dtnow=100;
      if(beltOn)beltT+=dtnow;
    }
    lastFrameMs=now;
    var tx=(beltT/1000*VJ)%80;
    get('gla-treads').setAttribute('transform','translate('+tx.toFixed(2)+',0)');
    var ang=((beltT/1000*3.6)%360); // 轮辐随带面时间缓慢旋转 (冻结即停)
    get('gla-spoke-1').setAttribute('transform','rotate('+ang.toFixed(1)+' 70 400)');
    get('gla-spoke-2').setAttribute('transform','rotate('+ang.toFixed(1)+' 1110 400)');
    // 环境供血 (仅模拟源): 无真实任务时随机物料上带 — 间距不均匀 (1.5s~5.5s),
    // 随机道, 直通到带尾离场 (推杆不动作, 任何仓库不截留)
    if('sim'===srcMode){
      if(!td.active_job){
        if(now>=nextAmb){
          var freeL=[];
          for(var fi=0;3>fi;fi++){if(!journey[fi])freeL[freeL.length]=fi;}
          if(freeL.length>0){
            var fl=freeL[Math.floor(Math.random()*freeL.length)];
            var pm=POOL8[Math.floor(Math.random()*POOL8.length)];
            startJourney(fl,X0,now,'pass');
            journey[fl].mat={m:pm.m,label:pm.label,color:pm.color};
            nextAmb=now+1500+Math.floor(Math.random()*4000); // 间隔随机 → 带面件距不均匀
            setVariant(fl,pm.m);
          }
        }
      }
    }
    var msgJ='';
    for(var i=0;3>i;i++){
      var si=td.sorters?(td.sorters[i]||{}):{};
      var st=si.state||'ready', ts=si.ts_ms||0;
      setVariant(i,jmat(i)?jmat(i).m:'block'); // 物品图标随旅程物料切换 (任务/供血)
      var rod=get('gla-rod-'+(i+1));
      if('armed'===st){ // 光门落沿事件 (新的) → 启动回放
        if(ts>lastArmedMs[i]){
          lastArmedMs[i]=ts;
          if(journey[i]){if(journey[i].pass)journey[i]=null;} // 任务物品顶掉直通物品
          if(!journey[i]){
            // 模拟源: 全旅程 (带首装料); 真实源: 物品按实际状态出现在光门处 (事件驱动, 不虚构上游行程)
            startJourney(i,('device'===srcMode)?G[i]:X0,now,'gate');
          }
        }
      } else if('busy'===st){ // 推杆已在动作 (错过 armed 窗口 / 旧固件只发 busy): 物品就在推料点, 不虚构上游行程
        if(ts>lastBusyMs[i]){
          lastBusyMs[i]=ts;
          if(journey[i]){if(journey[i].pass)journey[i]=null;}
          if(!journey[i]){
            startJourney(i,P[i],now,'push');
            journey[i].phase='armed';
            journey[i].tArmed=now; // 推杆正在推出: 物品已在推料点, 带面即停
          }
        }
      }
      if('fault'===st){if(journey[i])journey[i]=null;}
      var j=journey[i];
      if(j){ // 全旅程: 带面时间轴走到推料点 → 停带 → 推杆推出 → 滑入料道 (时间 2:1 放慢)
        var nm=jmat(i)?String(jmat(i).label).split(' × ')[0]:'物品';
        if('travel'===j.phase){ // 沿带面行走 (随带面: 停带即停, 匀速到推料点, 无加速)
          var ix=j.x0+VJ*(beltT-j.b0)/1000;
          var gone=false;
          var adv=j.pass?false:(ix>=P[i]); // 任务物品到推料点: 停带, 推杆开始推出; 直通物品不停, 走满到带尾
          if(adv){ix=P[i];j.phase='armed';j.tArmed=now;}
          else{
            if(CAMX>j.x0){ // 物品经过 HuskyLens 2 视场: 相机处显示识别内容 (时间窗)
              var tcCam=j.b0+(CAMX-j.x0)/VJ*1000;
              if(beltT>=tcCam-150){if(tcCam+1200>=beltT)setVision(i,now);}
            }
          }
          if(j.pass){
            if(ix>=BEND){
              get('gla-obj-'+(i+1)).setAttribute('opacity','0');
              journey[i]=null;gone=true;
            } else {
              var opx=1;
              if(ix>(BEND-70))opx=(BEND-ix)/70; // 接近带尾淡出
              get('gla-obj-'+(i+1)).setAttribute('opacity',opx.toFixed(2));
            }
          } else {
            get('gla-obj-'+(i+1)).setAttribute('opacity','1');
          }
          if(!gone){
            get('gla-obj-'+(i+1)).setAttribute('transform','translate('+ix.toFixed(1)+',400)');
            rod.setAttribute('y2','438.0');
            rod.setAttribute('stroke','var(--gate-fg,#e6e6e6)');
            get('gla-chute-'+(i+1)).setAttribute('stroke-opacity','0.30');
            if(!j.pass)showLabel(i);
          }
          gateOr(j); // 光门虚线: 物品经过即亮 (本帧 OR 聚合, 循环后统一点亮, 多物品互不抹除)
          if(!msgJ){
            if(j.pass)msgJ=nm+' 沿带面行走 · 无下发指令直通';
            else msgJ=nm+' 沿带面行走 → '+(i+1)+'号仓 (HuskyLens 2 识别)';
          }
        } else if('armed'===j.phase){ // 推料中: 带面已停, 物品停在推料点, 推杆推出 450ms
          var ex=ease(Math.min(1,(now-j.tArmed)/450));
          rod.setAttribute('y2',(438-36*ex).toFixed(1));
          rod.setAttribute('stroke','var(--gate-acc,#fb923c)');
          get('gla-chute-'+(i+1)).setAttribute('stroke-opacity','0.55');
          get('gla-obj-'+(i+1)).setAttribute('opacity','1');
          get('gla-obj-'+(i+1)).setAttribute('transform','translate('+P[i].toFixed(1)+',400)');
          showLabel(i);
          if((now-j.tArmed)>=450){j.phase='busy';j.tBusy=now;}
          if(!msgJ)msgJ='带面已停 · 推杆 '+(i+1)+' 推出 (行程 450ms)';
        } else if('busy'===j.phase){ // 拨入: 物品沿 45° 滑入料道
          var p2=(now-j.tBusy)/900;
          rod.setAttribute('y2','402.0');
          rod.setAttribute('stroke','var(--gate-acc,#fb923c)');
          get('gla-chute-'+(i+1)).setAttribute('stroke-opacity','0.75');
          var cc=Math.max(0,(p2-0.35))*CHL/0.65; if(cc>CHL)cc=CHL;
          var op2=cc>=CHL-8?Math.max(0,(CHL-cc)/8):1;
          get('gla-obj-'+(i+1)).setAttribute('opacity',op2.toFixed(2));
          get('gla-obj-'+(i+1)).setAttribute('transform','translate('+(P[i]+C45*cc).toFixed(1)+','+(400+C45*cc).toFixed(1)+')');
          showLabel(i);
          if(p2>=1){
            // 仅模拟源逐件回放内部推进; 真实源按后续事件推进 (每件一个旅程)
            var adv=false;
            if('sim'===srcMode){if(j.task){if(j.left>0){j.left--;j.phase='wait';j.tWait=now;adv=true;}}}
            if(!adv)journey[i]=null;
          }
          if(!msgJ)msgJ='第 '+(j.qty-j.left)+' 件拨入 '+(i+1)+' 号料道 ✓';
        } else { // wait (模拟源逐件回放): 件间间隙, 带面恢复, 下一件带首装料
          rod.setAttribute('y2','438.0');
          rod.setAttribute('stroke','var(--gate-fg,#e6e6e6)');
          get('gla-chute-'+(i+1)).setAttribute('stroke-opacity','0.30');
          get('gla-obj-'+(i+1)).setAttribute('opacity','0');
          showLabel(i);
          if(now-j.tWait>=700){
            j.phase='travel';
            j.x0=X0;
            j.b0=beltT;
          }
          if(!msgJ)msgJ=(i+1)+'号仓 · 下一件待发';
        }
      } else { // 无旅程: 原状态还原 (fault/ready/错过窗口兜底)
        var p=0; if(ts){p=(now+td.t0-ts)/900; if(p>1)p=1;} // 350ms 蓄能 + 推出拨入 ≈ 900ms
        if('armed'===st){ // 光门已触发, 推杆推出中 (450ms)
          var ex=ease(Math.min(1,(now+td.t0-ts)/450));
          rod.setAttribute('y2',(438-36*ex).toFixed(1));
          rod.setAttribute('stroke','var(--gate-acc,#fb923c)');
          get('gla-chute-'+(i+1)).setAttribute('stroke-opacity','0.55');
          get('gla-obj-'+(i+1)).setAttribute('opacity','0');
          showLabel(i);
        } else if('busy'===st){ // 推出完成, 物品滑入料道
          rod.setAttribute('y2','402.0');
          rod.setAttribute('stroke','var(--gate-acc,#fb923c)');
          get('gla-chute-'+(i+1)).setAttribute('stroke-opacity','0.75');
          var cc=Math.max(0,(p-0.35))*CHL/0.65; if(cc>CHL)cc=CHL;
          var op2=cc>=CHL-8?Math.max(0,(CHL-cc)/8):1;
          get('gla-obj-'+(i+1)).setAttribute('opacity',op2.toFixed(2));
          get('gla-obj-'+(i+1)).setAttribute('transform','translate('+(P[i]+C45*cc).toFixed(1)+','+(400+C45*cc).toFixed(1)+')');
          showLabel(i);
        } else if('fault'===st){ // 故障: 光门红色告警, 推杆不动作
          rod.setAttribute('y2','438.0');
          rod.setAttribute('stroke','var(--gate-fg,#e6e6e6)');
          get('gla-chute-'+(i+1)).setAttribute('stroke-opacity','0.30');
          get('gla-obj-'+(i+1)).setAttribute('opacity','0');
          hideLabel(i);
        } else { // ready: 静止
          rod.setAttribute('y2','438.0');
          rod.setAttribute('stroke','var(--gate-fg,#e6e6e6)');
          get('gla-chute-'+(i+1)).setAttribute('stroke-opacity','0.30');
          get('gla-obj-'+(i+1)).setAttribute('opacity','0');
          hideLabel(i);
        }
      }
    }
    // 光门虚线: 逐道处理完后统一判定 — 全部物品"过门时间窗"OR + 本道推料保持点亮 +
    // 故障红色告警. 多物品同时在带面时互不抹除 (任一物品在窗口内即亮, 掉帧不丢).
    for(var gk=0;3>gk;gk++){
      var gs=(td.sorters?(td.sorters[gk]||{}):{})||{};
      var gst=gs.state||'ready';
      var gj2=journey[gk];
      var gOn=(('armed'===gst)||('busy'===gst));
      if(gj2){if('armed'===gj2.phase){gOn=true;}else if('busy'===gj2.phase){gOn=true;}}
      var gg=get('gla-gate-'+(gk+1));
      if('fault'===gst){gg.setAttribute('opacity','0.90');gg.setAttribute('stroke','#f87171');}
      else if(gOn||gateLit[gk]){gg.setAttribute('opacity','0.80');gg.setAttribute('stroke','var(--gate-acc,#fb923c)');}
      else{gg.setAttribute('opacity','0');gg.setAttribute('stroke','var(--gate-acc,#fb923c)');}
    }
    // 相机识别显示 (HuskyLens 2 处: 物料名 + 去向; 模拟源过相机时出现, 真实源按事件出现)
    var visOn=false;
    if(visUntil>now)visOn=true;
    get('gla-visiong').setAttribute('opacity',visOn?'1':'0');
    if(visOn)get('gla-vision').textContent=visLabel;
    get('gla-fan').setAttribute('opacity',visOn?'0.35':'0.10');
    get('gla-cam').setAttribute('stroke',visOn?'var(--gate-acc,#fb923c)':'var(--gate-bd,#262b36)');
    get('gla-status').textContent=msgJ||('sim'===srcMode?'模拟运行 · 物料无指令直通 (下发指令后按 HuskyLens 2 识别结果拨入指定仓库)':td.status||'数字孪生在线 · 等待事件…');
  }
  var mqr=null;
  if(window.matchMedia){mqr=window.matchMedia('(prefers-reduced-motion: reduce)');}
  var motionOff=false;
  if(mqr){
    if(mqr.matches){
      motionOff=true;
      get('gla-status').textContent='（系统偏好「减少动态效果」: 循环演示停用; 数字孪生在线时仍逐帧更新状态）';
    }
  }
  window.__gla={render:render,twinFrame:twinFrame,
    setTwin:function(d){ twinData=d; twinMode=true;
      if(!booted){booted=true; // 载入时的快照作基线, 只有更新的事件才触发旅程 (避免重放旧事件)
        var ss=d.sorters||[];
        for(var i=0;3>i;i++){
          var ee=ss[i]||{};
          lastArmedMs[i]=ee.ts_ms||0;
          lastBusyMs[i]=ee.ts_ms||0;
        }
      }
      if(motionOff){twinFrame(performance?performance.now():Date.now());} },
    beltBusy:function(){for(var i=0;3>i;i++){if(journey[i])return true;}return false;},
    setSrc:function(s){ // 数据源: sim=本地孪生模拟器 (开环境供血, 全旅程) / device=物理设备 (事件驱动, 不在真实事件上虚构物品)
      srcMode=(s==='sim')?'sim':'device';
      if('sim'===srcMode)nextAmb=0;
      else{ // 切到真实源: 清掉孪生视图在带面的一切物品 (事件驱动: 只有真实事件才让物品出现, 不虚构)
        for(var i=0;3>i;i++){journey[i]=null;}
      }
      if(motionOff){twinFrame(performance?performance.now():Date.now());}
    },
    demo:function(){ twinMode=false; twinData=null; start=null; demoPick(); },
    setJob:function(list){ // 页面下发后注入本任务物料: [{yard, material, label:'香蕉 ×2', color, qty}]
      for(var i=0;3>i;i++)jobMats[i]=null;
      var arr=list||[];
      var taskLane={};
      for(var tk=arr.length;tk>0;tk--){
        var it2=arr[tk-1];
        if(it2){if(it2.yard>=1){if(3>=it2.yard)taskLane[it2.yard-1]=true;}}
      }
      for(var i0=0;3>i0;i0++){
        if(taskLane[i0]){if(journey[i0])journey[i0]=null;} // 真实任务接管该道: 取消供血项
      }
      for(var a=arr.length-1;a>=0;a--){
        var it=arr[a];
        if(it){
          if(it.yard>=1){
            if(3>=it.yard)jobMats[it.yard-1]={m:it.material,label:it.label,color:it.color,qty:it.qty};
          }
        }
      }
      for(var i=0;3>i;i++)setVariant(i,jobMats[i]?jobMats[i].m:'block');
      if(motionOff){twinFrame(performance?performance.now():Date.now());} },
    TEND:TEND,S:S,TC:TC,TG:TG,TD:TD}; // 测试钩子 (桩驱动)
  var start=null;
  var lastCyc=-1;
  function step(now){
    if(twinMode){ twinFrame(now); }
    else {
      if(null==start)start=now;
      var t=(now-start)/1000;
      if(0>t)t=0;
      var cyc=Math.floor(t/TEND);
      if(cyc!==lastCyc){lastCyc=cyc;demoPick();} // 换轮: 重新随机 3 种物料
      render(t%TEND);
    }
    requestAnimationFrame(step);
  }
  if(!motionOff)requestAnimationFrame(step);
})();
